import AxeBuilder from '@axe-core/playwright';
import assert from 'node:assert/strict';import {mkdtemp,cp,readFile,writeFile,rm} from 'node:fs/promises';import path from 'node:path';import {tmpdir} from 'node:os';import {chromium} from 'playwright';import {extract} from '../../engine/extract.mjs';import {run} from '../../engine/pipeline.mjs';import {serveStatic} from '../../engine/static.mjs';import {visualScore} from '../../engine/verify.mjs';import {refreshComponentScripts} from './refresh-component-scripts.mjs';
const artifact=path.resolve(process.argv[2]||'artifacts/platform/wpforms-heldout'),temp=await mkdtemp(path.join(tmpdir(),'wpf-validation-'));let browser,server;const cases=[], accessibility=[];
try{
 await cp(path.join(artifact,'project'),temp,{recursive:true});if(!process.argv.includes('--generated'))await refreshComponentScripts(temp);
 const captured=JSON.parse(await readFile(path.join(artifact,'captured-model.json'))),record=captured.pages.find(p=>p.route==='/workshop-interest/');const contract=extract(record.sourceHTML,record.url).sourceForms.find(f=>f.provider==='wpforms');assert.ok(contract.fields[0].validationMessages);contract.delivery={endpoint:'/local-validation',format:'json'};
 const config=JSON.parse(await readFile(path.join(temp,'forms.json')));config.forms=config.forms.map(f=>f.id===contract.id?contract:f);await writeFile(path.join(temp,'forms.json'),JSON.stringify(config));await run(process.execPath,['scripts/build.mjs'],{cwd:temp,timeout:120000});server=await serveStatic(path.join(temp,'output'));browser=await chromium.launch({channel:'chrome'});
 for(const width of [1440,390]){
  const states=[];for(const [kind,url]of [['source','http://127.0.0.1:9439/workshop-interest/'],['rebuilt',server.url+'/workshop-interest/']]){
   const context=await browser.newContext({viewport:{width,height:844},reducedMotion:'reduce'});const page=await context.newPage();let posts=0;
   await page.route('**/*',r=>{if(!['GET','HEAD'].includes(r.request().method())){posts++;return r.abort();}return new URL(r.request().url()).origin===new URL(url).origin?r.continue():r.abort();});await page.goto(url,{waitUntil:'networkidle'});await page.evaluate(()=>document.fonts.ready);await page.locator('form.wpforms-form button[type=submit]').click();await page.waitForSelector('em.wpforms-error');await page.waitForTimeout(1000);const state=await page.locator('form.wpforms-form').evaluate(f=>({errors:[...f.querySelectorAll('em.wpforms-error')].map(e=>e.textContent),wrappers:f.querySelectorAll('.wpforms-has-error').length,inlineInsideChoice:!!f.querySelector('.choices em.wpforms-error'),emailBorders:[...f.querySelectorAll('input[type=email]')].map(e=>getComputedStyle(e).borderTopColor)}));   const file=path.join(artifact,`validation-${kind}-${width}.png`);await page.screenshot({path:file,fullPage:true,animations:'disabled'});states.push({...state,file});if(kind==='rebuilt'){
    const audit=await new AxeBuilder({page}).include('form.wpforms-form').analyze();
    assert.deepEqual(audit.violations.filter(v=>v.id!=='color-contrast').map(v=>v.id),[],'Unexpected form accessibility violations');
    const invalid=await page.locator('form.wpforms-form [aria-invalid="true"]').evaluateAll(els=>els.map(e=>({name:e.name,described:(e.getAttribute('aria-describedby')||'').split(/\s+/).filter(Boolean).some(id=>Boolean(document.getElementById(id)?.textContent.trim()))})));
    assert.ok(invalid.length>0,'Invalid controls must expose their state');assert.ok(invalid.every(e=>e.described),'Each invalid control must reference its error: '+JSON.stringify(invalid));
    await page.keyboard.press('Tab');const keyboard=await page.evaluate(()=>({tag:document.activeElement?.tagName,visible:!!document.activeElement?.getClientRects().length}));assert.ok(keyboard.visible&&keyboard.tag!=='BODY','Keyboard focus must remain usable after validation');
    accessibility.push({width,invalid,keyboard,violations:audit.violations.map(v=>({id:v.id,impact:v.impact,count:v.nodes.length}))});
   }
assert.equal(posts,0);await context.close();
  }
  assert.deepEqual(states[1].errors,states[0].errors);assert.equal(states[1].wrappers,states[0].wrappers);assert.equal(states[1].inlineInsideChoice,false);const pixel=visualScore(await readFile(states[0].file),await readFile(states[1].file));cases.push({width,pixel,errors:states[1].errors,wrappers:states[1].wrappers,sourceEmailBorders:states[0].emailBorders,rebuiltEmailBorders:states[1].emailBorders,borderParity:JSON.stringify(states[0].emailBorders)===JSON.stringify(states[1].emailBorders)});assert.ok(pixel>=.99,'Error-state visual mismatch '+pixel);assert.ok(cases.at(-1).borderParity,'Error-border colours differ: '+JSON.stringify(cases.at(-1)));
 }
 await writeFile(path.join(artifact,'validation-check.json'),JSON.stringify({generatedScripts:process.argv.includes('--generated'),cases,accessibility,sourceSubmissions:0,aiCalls:0},null,2));console.log(JSON.stringify({cases,accessibility}));
}finally{await browser?.close();await server?.close();await rm(temp,{recursive:true,force:true});}
